using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Breaking change #1: EF Core 9 renames the discriminator property
            // from "Discriminator" to "$type". Our 500K existing documents and
            // direct SQL queries use "Discriminator", so preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change #2: EF Core 9 stops prepending the discriminator
            // to the id value (was "Product|123", now just "123"). Existing
            // documents use the old format, so opt back in to keep compatibility.
            entity.HasPartitionKey(e => e.Id);
            entity.Property(e => e.Id)
                  .HasConversion(
                      id => $"Product|{id}",
                      dbId => int.Parse(dbId.Replace("Product|", "")));
        });
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Breaking change #3: EF Core 9 Cosmos provider no longer supports
        // HasIndex(). Cosmos manages indexing via its own indexing policy, not
        // EF model indexes. The HasIndex() call has been removed above.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

